  log(`wrote ${findingsPath} (findings=${findings.length})`);
  log(`wrote ${verdictPath}`);
  for (const f of findings) {
    log(`  finding ${f.id} [${f.severity}] ${f.title}`);
  }
  log('WT-017 Perfetto explore MVP done');

